import{_ as l,o as t,c as n,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- OSD: RADOS I/O Hints","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- OSD: RADOS I/O Hints","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","I/O优化","OSD","RADOS","Ceph存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_RADOS_I_O_Hints.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_RADOS_I_O_Hints.md","lastUpdated":1780459816000}'),_={name:"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_RADOS_I_O_Hints.md"};function e(a,i,r,o,p,O){return t(),n("div",null,[...i[0]||(i[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： OSD I/O 提升方案讨论</p><p><strong>会议时间</strong>： 2023年X月X日</p><p><strong>参会人员</strong>： John, Ping, 研发团队</p><p><strong>会议内容</strong>：</p><ul><li><p><strong>议题一：OSD I/O 提升方案</strong></p><ul><li>John介绍了Ceph中OSD I/O提升的方案，旨在提高客户端使用Ceph的效率。该方案利用了Ceph的认证框架、Live RBD和RBD库支持，并通过手动修改代码来实现。</li><li>该方案使用CodeBunch作为I/O优化器，并通过手动修改代码来支持文件系统操作，优化内存使用和减少磁盘读取操作，以提高系统吞吐量和内存利用率。</li></ul></li><li><p><strong>议题二：IO hints的应用</strong></p><ul><li>讨论了IO hints在Ceph中的应用，包括： <ul><li>在文件系统中使用mount选项来控制I/O缓存行为。</li><li>在RBD中使用不同的缓存策略，如不缓存、使用代理读取等。</li><li>在后台操作中使用no-catch选项来避免缓存热点数据。</li></ul></li><li>讨论了IO hints的局限性，例如： <ul><li>Linux内核不支持无缓存读取操作。</li><li>需要考虑多客户端同时访问同一对象时的缓存策略。</li><li>需要权衡缓存和性能之间的平衡。</li></ul></li></ul></li><li><p><strong>议题三：后续行动计划</strong></p><ul><li>继续在Hammer版本中实现IO hints框架，并在Live Lab中进行测试。</li><li>评估并实现更多IO hints选项，例如： <ul><li>物理设备缓存选项。</li><li>虚拟设备缓存选项。</li><li>后台操作缓存选项。</li></ul></li><li>优化IO hints的实现，解决Linux内核不支持无缓存读取操作的问题。</li></ul></li></ul><p><strong>决定事项</strong>：</p><ul><li>继续推进IO hints的实现，并评估更多应用场景。</li><li>在Hammer版本中实现IO hints框架，并在Live Lab中进行测试。</li><li>优化IO hints的实现，解决Linux内核不支持无缓存读取操作的问题。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>研发团队将根据会议讨论结果，继续推进IO hints的实现。</li><li>研发团队将与内核社区合作，解决Linux内核不支持无缓存读取操作的问题。</li><li>研发团队将定期更新会议纪要，并汇报项目进展。</li></ul>',10)])])}const I=l(_,[["render",e]]);export{u as __pageData,I as default};
